-- puzzles.lua: the puzzles of Sudoku, filed under the band the shipped solver needs. Generated by
-- make_bank.py (kept with the game's checks); edit nothing here by hand.
--
-- Source: the Sudoku Exchange puzzle bank, https://github.com/grantm/sudoku-exchange-puzzle-bank, commit d8c8ebaee0c08c412cfba96af1923dfa61c83317.
-- Puzzles from the Sudoku Exchange puzzle bank (sudokuexchange.com), public domain.
-- Records: easy.txt, medium.txt, hard.txt (774235 read, 0 dropped for a hash that is not the first 12 hex
-- digits of the SHA-1 of the digits); merged in hash order and graded in that order.
-- Settings: 100 per band, cap 1000000 instructions, count cap 1500000, 20 records to a string,
-- solver.lua.
-- A record is hash12 .. digits81 (0 for an empty cell). A band is the hardest technique the solver needs: Easy
-- singles, Medium locked candidates, Hard pairs, Expert anything above. A puzzle the solver cannot finish, or whose
-- worst single call (grade, or answer then hint, plus the solver's one-time table building) passes the cap, is left out;
-- so is one the checks' independent counter does not find exactly one solution of within the count cap.
-- Measured with a host Lua 5.5.1, instructions counted one by one: the solver's one-time table building takes
-- 11023. Candidates graded: 1195, of which 202 are not finished by the ladder.
-- Easy: examined 100, kept 100, over the cap 0, not countable 0, largest worst call kept 126112, examined 126112.
-- Medium: examined 100, kept 100, over the cap 0, not countable 0, largest worst call kept 124175, examined 124175.
-- Hard: examined 100, kept 100, over the cap 0, not countable 0, largest worst call kept 141742, examined 141742.
-- Expert: examined 100, kept 100, over the cap 0, not countable 0, largest worst call kept 224973, examined 224973.

local puzzles = {
  commit = "d8c8ebaee0c08c412cfba96af1923dfa61c83317",
  per = 20, -- records to a string
  width = 93, -- characters in a record
  cap = 1000000, -- the most instructions a worst single call may take
  count = { 100, 100, 100, 100 }, -- puzzles per band
  most = { 126112, 124175, 141742, 224973 }, -- largest worst-call cost kept
  -- the indices of the costliest few puzzles of each band, the costliest first
  costly = {
    { 28, 27, 74, 49 },
    { 59, 51, 8, 88 },
    { 21, 77, 67, 98 },
    { 59, 72, 48, 4 },
  },
  easy = {
    "",
    "",
    "",
    "",
    "",
  },
  medium = {
    "",
    "",
    "",
    "",
    "",
  },
  hard = {
    "",
    "",
    "",
    "",
    "",
  },
  expert = {
    "",
    "",
    "",
    "",
    "",
  },
}

-- puzzles.get(band, i) -> hash12, digits81: puzzle i (from 1) of band 1 (Easy) to 4 (Expert).
local KEYS = { "easy", "medium", "hard", "expert" }
function puzzles.get(band, i)
  local chunk = puzzles[KEYS[band]][(i - 1) // puzzles.per + 1]
  local at = ((i - 1) % puzzles.per) * puzzles.width + 1
  return chunk:sub(at, at + 11), chunk:sub(at + 12, at + puzzles.width - 1)
end

return puzzles
